  merged.coins=Number(s?.coins||0);merged.longestStreak=Number(s?.longestStreak||s?.streak||0);
  merged.lastBackupAt=s?.lastBackupAt||null;merged.rewardedEventIds=Array.isArray(s?.rewardedEventIds)?s.rewardedEventIds:[];merged.bossClaims=Array.isArray(s?.bossClaims)?s.bossClaims:[];merged.bossHistory=Array.isArray(s?.bossHistory)?s.bossHistory:[];merged.testMode={...freshTestSandbox(false),...(s?.testMode||{})};merged.schemaVersion='3.2.1';merged.appVersion=APP_VERSION;
