const notifications=new NotificationQueue();
function scheduleNotification(){if(notificationTimer)clearTimeout(notificationTimer);const current=notifications.current();if(current&&current.dismissAfterMs>0)notificationTimer=setTimeout(()=>notifications.dismiss(current.notificationId),current.dismissAfterMs)}
notifications.subscribe(()=>{scheduleNotification();if(typeof state!=='undefined'&&state)render()});
function notify(title:string,message:string,type:NotificationType='success',dismissAfterMs=3500,actionLabel?:string){notifications.enqueue({type,title,message,dismissAfterMs,dismissible:true,actionLabel})}
function toast(message:string,kind='success'){const type:NotificationType=kind==='achievement'?'achievement':kind==='error'?'error':'success';notify(type==='achievement'?'Achievement unlocked':type==='error'?'Action needed':'Done',message,type,type==='error'?8000:3500)}
function level(){return Math.max(1,Math.floor(state.xp/250)+1)}
function awardOnce(key:string,coins:number,eventType:string,payload:Record<string,unknown>):boolean{
  if(state.rewardedEventIds.includes(key))return false;
  state.rewardedEventIds.push(key);
  state.coins+=coins;
  state.events.push(emit(eventType,[],{...payload,rewardKey:key,coins}));
  return true;
}
const achievementDefs=[
{id:'first-lesson',name:'First Lesson',coins:2,progress:()=>state.events.some(e=>e.type==='concept_introduced')?1:0,target:1},
{id:'first-correct',name:'First Correct Answer',coins:2,progress:()=>state.events.filter(e=>e.type==='activity_answered'&&e.payload.correct===true).length,target:1},
{id:'first-understood',name:'First Concept Understood',coins:3,progress:()=>Object.values(state.progress).filter(p=>['understood','applied','retained','exam-ready'].includes(p.stage)).length,target:1},
{id:'first-applied',name:'First Concept Applied',coins:3,progress:()=>Object.values(state.progress).filter(p=>['applied','retained','exam-ready'].includes(p.stage)).length,target:1},
{id:'first-retained',name:'First Concept Retained',coins:5,progress:()=>Object.values(state.progress).filter(p=>['retained','exam-ready'].includes(p.stage)).length,target:1},
{id:'first-exam-ready',name:'First Exam-Ready Concept',coins:5,progress:()=>Object.values(state.progress).filter(p=>p.stage==='exam-ready').length,target:1},
{id:'ten-understood',name:'10 Concepts Understood',coins:5,progress:()=>Object.values(state.progress).filter(p=>['understood','applied','retained','exam-ready'].includes(p.stage)).length,target:10},
{id:'fifty-understood',name:'50 Concepts Understood',coins:10,progress:()=>Object.values(state.progress).filter(p=>['understood','applied','retained','exam-ready'].includes(p.stage)).length,target:50},
{id:'hundred-questions',name:'100 Questions Answered',coins:10,progress:()=>state.events.filter(e=>e.type==='activity_answered').length,target:100},
{id:'five-hundred-questions',name:'500 Questions Answered',coins:30,progress:()=>state.events.filter(e=>e.type==='activity_answered').length,target:500},
{id:'seven-day-streak',name:'Seven Day Streak',coins:10,progress:()=>state.streak,target:7},
{id:'thirty-day-streak',name:'Thirty Day Streak',coins:30,progress:()=>state.streak,target:30},
{id:'first-pbq',name:'First PBQ Completed',coins:5,progress:()=>state.events.filter(e=>e.type==='activity_answered'&&String(e.payload.activityType).includes('pbq')).length,target:1},
{id:'first-boss-battle',name:'First Boss Battle',coins:2,progress:()=>state.bossHistory.length,target:1},
{id:'first-boss',name:'First Boss Defeated',coins:10,progress:()=>state.bossHistory.filter(b=>b.passed).length,target:1},
{id:'perfect-boss',name:'Perfect Boss Battle',coins:15,progress:()=>state.bossHistory.filter(b=>b.passed&&b.score===100).length,target:1},
{id:'first-objective-boss',name:'First Objective Boss',coins:15,progress:()=>state.bossHistory.filter(b=>b.passed&&b.bossType==='objective').length,target:1},
{id:'first-domain-boss',name:'First Domain Boss',coins:25,progress:()=>state.bossHistory.filter(b=>b.passed&&b.bossType==='domain').length,target:1},
{id:'acronym-apprentice',name:'Acronym Apprentice',coins:8,progress:()=>acronyms.filter(r=>state.progress[r.conceptId]?.stage!=='unseen').length,target:50},
{id:'acronym-expert',name:'Acronym Expert',coins:25,progress:()=>acronyms.filter(r=>['retained','exam-ready'].includes(state.progress[r.conceptId]?.stage)).length,target:200},
{id:'security-plus-ready',name:'Security+ Exam Ready',coins:50,progress:()=>Object.values(state.progress).filter(p=>p.stage==='exam-ready').length,target:300}
];
function checkAchievements(){for(const a of achievementDefs){const unlocked=a.progress()>=a.target;if(!state.achievements.includes(a.id)&&unlocked){state.achievements.push(a.id);awardOnce(`achievement:${a.id}`,a.coins,'achievement_unlocked',{achievementId:a.id,unlockedAt:iso()});toast(`Achievement unlocked: ${a.name} (+${a.coins} coins)`,'achievement')}}}
const shieldTiers=[
{id:'shield-bronze',name:'Bronze',requires:'10 understood and first Unit Boss',test:()=>countStages('understood')>=10&&bossCount('unit')>=1},
{id:'shield-silver',name:'Silver',requires:'50 understood, 20 applied and 3 Unit Bosses',test:()=>countStages('understood')>=50&&countStages('applied')>=20&&bossCount('unit')>=3},
{id:'shield-gold',name:'Gold',requires:'150 understood, 75 applied, 25 retained and an Objective Boss',test:()=>countStages('understood')>=150&&countStages('applied')>=75&&countStages('retained')>=25&&bossCount('objective')>=1},
{id:'shield-platinum',name:'Platinum',requires:'300 understood, 150 applied, 75 retained and 2 Domain Bosses',test:()=>countStages('understood')>=300&&countStages('applied')>=150&&countStages('retained')>=75&&bossCount('domain')>=2},
{id:'shield-diamond',name:'Diamond',requires:'450 understood, 300 applied, 200 retained and all 5 Domain Bosses',test:()=>countStages('understood')>=450&&countStages('applied')>=300&&countStages('retained')>=200&&bossCount('domain')>=5},
{id:'shield-master',name:'Security+ Master',requires:'80% estimated readiness, 300 exam-ready, 400 retained and Final Boss',test:()=>estimatedReadiness()>=80&&countStages('retained')>=400&&countStages('exam-ready')>=300&&bossCount('final')>=1}
];
function countStages(stage:Stage){const order:Stage[]=['unseen','introduced','recognised','understood','applied','retained','exam-ready'],i=order.indexOf(stage);return Object.values(state.progress).filter(p=>order.indexOf(p.stage)>=i).length}
function bossCount(type:string){return state.bossHistory.filter(b=>b.passed&&b.bossType===type).length}
function estimatedReadiness(){const ps=Object.values(state.progress);return ps.length?Math.round(ps.reduce((a,p)=>a+p.mastery,0)/ps.length):0}
function currentShield(){return [...shieldTiers].reverse().find(t=>t.test())||{id:'shield-basic',name:'Basic',requires:'Defeat your first Unit Boss'} }
function firstAttemptAccuracy(){const a=state.events.filter(e=>e.type==='activity_answered'&&!e.payload.testOnly);return a.length?Math.round(a.filter(e=>e.payload.correct===true&&Number(e.payload.attempts||1)===1).length/a.length*100):0}

function save(){state.appVersion=APP_VERSION;state.schemaVersion='3.2.1';localStorage.setItem(KEY,JSON.stringify(state))}
function saveProfile(){if(profile)localStorage.setItem(PROFILE_KEY,JSON.stringify(profile))}
function learnerName(){return profile?.name?.trim()||'Learner'}
function unitFor(cid:string){return units.learningUnits.find((u:any)=>u.conceptIds.includes(cid)||(u.acronymMappings||[]).some((a:any)=>a.acronymId===cid))||{unitId:'ACRONYM-POOL',name:'Acronym pool'}}
function rel(r:any){return concepts.filter(x=>x.objective===r.objective&&x.conceptId!==r.conceptId).sort(()=>Math.random()-.5).slice(0,3)}
function toActivity(q:ContentQuestion,why:string):Activity{return {id:q.questionId,conceptId:q.conceptId,unitId:q.unitId,type:q.activityType,prompt:q.prompt,options:[...q.options].sort(()=>Math.random()-.5),correct:[q.correctAnswer],reason:q.shortExplanation,distractorReasons:q.explanations,memoryCue:q.memoryCue,examTrap:q.examTip,microsoftExample:q.microsoftExample||'',mspExample:q.mspExample||'',selectionReason:why,qualityStatus:q.review.approvedForExam?'approved':q.review.approvedForBoss?'reviewed':'reviewed',difficulty:q.difficulty,objective:q.objective,commonWrongTemptation:'This option is plausible because it belongs to the same decision space, but a detail in the scenario rules it out.',sourceRefs:['approved-curriculum-v1.2'],contentVersion:q.contentVersion};}
function makeActivity(r:any,why:string):Activity{const question=contentPack.questions.find(q=>q.conceptId===r?.conceptId&&q.review.approvedForLearn);if(!question)throw Error('No reviewed question is available for this concept.');return toActivity(question,why)}
function scoreQuestion(q:ContentQuestion,mode:string){const p=state.progress[q.conceptId]||blank(q.conceptId);return (p.nextReview&&new Date(p.nextReview)<=new Date()?45:0)+(p.stage==='unseen'?20:0)+(100-p.mastery)*.35+p.misconceptions.length*8+(mode==='mistakes'&&p.attempts>p.correct?80:0)+(mode==='low-confidence'&&p.guesses>0?80:0)+Math.random()*8}
function createSession(minutes:number,mode='adaptive'):Session{
 const boss=mode==='boss'||mode.startsWith('boss-'),exam=mode==='exam';
 const contentMode=exam?'exam':boss?'boss':'learn';let pool=eligibleQuestions(contentPack,contentMode);
 if(mode==='due')pool=pool.filter(q=>state.progress[q.conceptId]?.nextReview&&new Date(state.progress[q.conceptId].nextReview!)<=new Date());
 if(mode==='mistakes')pool=pool.filter(q=>{const p=state.progress[q.conceptId];return p&&(p.attempts>p.correct||p.misconceptions.length>0)});
 if(mode==='low-confidence')pool=pool.filter(q=>{const p=state.progress[q.conceptId];return p&&(p.guesses>0||(p.attempts>0&&p.confidenceAccuracy<55))});
 if(mode==='comparison')pool=pool.filter(q=>q.activityType==='compare'||state.progress[q.conceptId]?.misconceptions.length);
 if(!pool.length)throw Error(exam?'Exam Mode has no approved questions yet. Reviewed content will be added in the editorial releases.':'No reviewed questions are currently available for this session. Open Learn to study a concept instead.');
 const bossType:(Session['bossType'])=mode==='boss-final'?'final':mode==='boss-domain'?'domain':mode==='boss-objective'?'objective':'unit';
 const counts={unit:5,objective:8,domain:12,final:15},thresholds={unit:70,objective:75,domain:80,final:85},rewards={unit:10,objective:25,domain:75,final:150};
 const count=boss?counts[bossType!]:Math.max(1,Math.min(pool.length,Math.ceil(minutes*(minutes<=1?1:1.1))));
 const recentConcepts:string[]=[];const recentPrompts=new Set<string>();const picked:ContentQuestion[]=[];
 for(const q of [...pool].sort((a,b)=>scoreQuestion(b,mode)-scoreQuestion(a,mode))){if(recentPrompts.has(q.prompt))continue;if(recentConcepts.slice(-10).includes(q.conceptId))continue;picked.push(q);recentPrompts.add(q.prompt);recentConcepts.push(q.conceptId);if(picked.length>=count)break}
 const activities=picked.map(q=>toActivity(q,boss?'Boss milestone':mode==='mistakes'?'Previous mistake':mode==='low-confidence'?'Low-confidence evidence':mode==='comparison'?'Comparison practice':'Reviewed learning content'));
 const session:Session={id:id(),minutes,mode,activities,index:0,startedAt:iso()};if(boss){session.bossType=bossType;session.bossId=`${bossType}:${activities[0]?.unitId||'reviewed'}`;session.bossThreshold=thresholds[bossType!];session.bossCorrect=0;session.bossReward=rewards[bossType!]}
 return session;
}
function start(minutes:number,mode='adaptive',testOnly=false){state.activeSession=createSession(minutes,mode);state.activeSession.testOnly=testOnly;if(!testOnly)state.events.push(emit('session_started',state.activeSession.activities.map(a=>a.conceptId),{minutes,mode,testOnly:false}));save();view='session';resetActivity();render()}
function completeBoss(s:Session){
  if(!s.bossId||!s.bossType)return;
  const total=s.activities.length,score=Math.round((s.bossCorrect||0)/Math.max(1,total)*100),passed=score>=(s.bossThreshold||70);
  if(s.testOnly){toast(`TEST MODE boss preview complete: ${score}%`);return}
  state.bossHistory.push({bossId:s.bossId,bossType:s.bossType,score,passed,completedAt:iso()});
  state.events.push(emit('boss_battle_completed',s.activities.map(a=>a.conceptId),{bossId:s.bossId,bossType:s.bossType,total,correct:s.bossCorrect||0,score,threshold:s.bossThreshold,passed}));
  if(passed&&!state.bossClaims.includes(s.bossId)){state.bossClaims.push(s.bossId);awardOnce(`boss:${s.bossId}`,s.bossReward||0,'boss_reward_claimed',{bossId:s.bossId,bossType:s.bossType});toast(`Boss defeated · ${score}% · +${s.bossReward} coins`,'achievement')}else if(passed)toast(`Boss defeated · ${score}% · reward already claimed`);else toast(`Boss survived · ${score}% · ${s.bossThreshold}% required. Retry when ready.`,'error');
}
function resetActivity(){selected=[];confidence='Fairly sure';attempt=1;guidance='';preAnswerFlag='';activityStarted=Date.now()}
function navigate(v:string){view=v;render()}
function shell(body:string){return `<header><button data-nav="home" aria-label="Home">⌂</button><div><strong>Security+ Adaptive Learning</strong><span>SY0-701 · ${esc(learnerName())} · v${APP_VERSION}</span></div>${navigator.onLine?'':'<span>Offline</span>'}${shieldMarkup('header')}${state?.testMode?.enabled?'<button class="testModeBadge" data-nav="testlab">TEST MODE</button>':''}</header>${body}<nav><button data-nav="home">⌂<small>Home</small></button><button data-nav="learn">▤<small>Learn</small></button><button data-action="review">◉<small>Review</small></button><button data-nav="dashboard">▥<small>Dashboard</small></button><button data-nav="more">•••<small>More</small></button></nav>`}
function home(){const ps=Object.values(state.progress),due=ps.filter(p=>p.nextReview&&new Date(p.nextReview)<=new Date()).length,mistakes=ps.filter(p=>p.attempts>p.correct||p.misconceptions.length).length,low=ps.filter(p=>p.guesses>0||p.confidenceAccuracy<55&&p.attempts>0).length,shield=currentShield();return shell(`<main class="shell"><section class="hero"><p class="eyebrow">SECURITY+ LEARNING EXPERIENCE · v${APP_VERSION}</p><div class="homeIdentity">${shieldMarkup('large')}<div><h1>Welcome back, ${esc(learnerName())}.</h1><p>${esc(shield.name)} shield · progress through real study evidence.</p></div></div><div class="heroStats"><span>Level ${level()}</span><span>${state.xp} XP</span><span>${state.coins} coins</span><span>${state.streak} day streak</span></div><button class="primary wide" data-start="5">Continue learning · 5 minutes</button></section><section class="actionGrid"><button data-mode="due" data-minutes="5">Reviews due <small>${due}</small></button><button data-mode="mistakes" data-minutes="5">Fix my mistakes <small>${mistakes}</small></button><button data-mode="low-confidence" data-minutes="5">Low confidence <small>${low}</small></button><button data-mode="acronym" data-minutes="5">Weak acronyms</button><button data-mode="comparison" data-minutes="5">Comparison practice</button><button data-nav="review">Boss battles</button><button data-nav="achievements">Achievements</button><button data-nav="cosmetics">Cosmetics</button><button data-nav="exam">Exam mode</button>${state.testMode.enabled?'<button data-nav="testlab">Developer Lab</button>':''}</section><section><h2>Quick sessions</h2><div class="durationGrid">${[[.5,'30 seconds'],[1,'1 minute'],[2,'2 minutes'],[5,'5 minutes'],[10,'10 minutes'],[15,'15 minutes']].map(([m,l])=>`<button data-start="${m}"><b>${l}</b></button>`).join('')}</div></section></main>`)}
function learn(){return shell(`<main class="shell"><h1>Learn mode</h1><p class="muted">Introduction is not mastery. Retrieval and application evidence are required.</p>${units.learningUnits.map((u:any)=>{const ps=u.conceptIds.map((x:string)=>state.progress[x]),done=ps.filter((p:Progress)=>p.stage!=='unseen').length;return `<section class="card"><div class="row"><span class="pill">${u.unitId}</span><span>${done}/${ps.length} introduced</span></div><h2>${esc(u.name)}</h2><p>${esc(u.unitSummary)}</p><div class="progress"><i style="width:${done/Math.max(1,ps.length)*100}%"></i></div><button class="primary" data-unit="${u.unitId}">${done?'Continue / review':'Start unit'}</button></section>`}).join('')}</main>`)}
function lesson(){const ids=[...currentUnit.conceptIds,...(currentUnit.acronymMappings||[]).filter((x:any)=>x.relationship==='core').map((x:any)=>x.acronymId)],r=records.find(x=>x.conceptId===ids[lessonIndex]),l=contentPack.lessons.find(x=>x.conceptId===r.conceptId);return shell(`<main class="shell"><div class="row"><span>${lessonIndex+1}/${ids.length}</span><span>${esc(currentUnit.name)}</span></div><div class="progress"><i style="width:${(lessonIndex+1)/ids.length*100}%"></i></div><section class="card lesson"><span class="pill">Objective ${esc(r.objective)}</span><h1>${esc(r.name)}</h1>${l?`<h3>What it is</h3><p class="lead">${esc(l.definition)}</p><h3>Why it matters</h3><p>${esc(l.purpose)}</p><h3>When it is used</h3><p>${esc(l.whenUsed)}</p><aside><b>Example</b><p>${esc(l.example)}</p></aside><div class="trap"><b>Common confusion</b><p>${esc(l.commonConfusion)}</p></div><div class="cue"><b>Memory cue</b><p>${esc(l.memoryCue)}</p></div><p><b>Exam distinction:</b> ${esc(l.examDistinction)}</p>`:`<p class="notice">A reviewed lesson for this concept is not available yet.</p><p><b>Official curriculum context:</b> ${esc(r.objectiveBranch)}</p><p>This concept will remain introduction-only until reviewed teaching content is added.</p>`}<div class="branchButtons"><button data-action="ask-ai">Explain current content</button><button data-action="save-cue">Save a note</button></div></section><div class="actions"><button data-action="lesson-prev" ${lessonIndex?'':'disabled'}>Previous</button><button class="primary" data-action="lesson-next">${lessonIndex+1===ids.length?'Complete unit':'Mark introduced and continue'}</button></div></main>`)}
function session(){const s=state.activeSession!,a=s.activities[s.index];if(!a){if(s.bossId){completeBoss(s);delete state.activeSession;checkAchievements();save();view='boss-result';return bossResultView()}delete state.activeSession;checkAchievements();save();view='dashboard';return dashboard()}const exam=s.mode==='exam';return shell(`<main class="shell questionScreen"><div class="row"><span>${exam?'Exam':s.bossId?'Boss battle':'Adaptive session'} · ${s.index+1}/${s.activities.length}</span><span>${exam?'No teaching':'Answer first'}</span></div><div class="progress"><i style="width:${(s.index+1)/s.activities.length*100}%"></i></div>${s.bossId?`<section class="bossArena"><div class="bossVisual ${s.bossType}" aria-hidden="true"><span class="bossCore">◆</span><b>${s.bossType==='final'?'RISK TITAN':s.bossType==='domain'?'IDENTITY GATEKEEPER':s.bossType==='objective'?'CERTIFICATE GUARDIAN':'ROGUE PROCESS'}</b></div>${bossConsole(s)}<section class="bossHud" aria-label="Boss health"><div class="bossTitle"><b>${esc(s.bossType)} boss</b><span>${s.bossThreshold}% required</span></div><div class="bossHealth"><i style="width:${Math.max(0,100-((s.bossCorrect||0)/Math.max(1,s.activities.length)*100))}%"></i></div><small>Boss health · ${Math.round(Math.max(0,100-((s.bossCorrect||0)/Math.max(1,s.activities.length)*100)))}%</small></section>`:''}${state.testMode.enabled?`<section class="selectionReason"><b>Developer selection reason:</b> ${esc(a.selectionReason)}</section>`:''}<section class="card question"><div class="row"><span class="pill">${esc(a.type)}</span>${state.testMode.enabled?`<span class="quality ${a.qualityStatus||'generated'}">${esc(a.qualityStatus==='generated'?'generated fallback':a.qualityStatus||'generated fallback')}</span>`:''}</div><h1>${esc(a.prompt)}</h1><div class="answers">${a.options.map(o=>`<button data-option="${encodeURIComponent(o)}" class="${selected.includes(o)?'selected':''}">${esc(o)}</button>`).join('')}</div>${exam?'':`<details class="flagPanel"><summary>Need help or want to flag how this feels?</summary><div class="flagActions"><button data-special="dontknow">I don’t know</button><button data-special="teach">Teach me</button><button data-special="forgot">I forgot</button><button data-special="confusing">I’m confusing this</button></div></details><button class="textButton" data-action="report-question">Report question</button>`}</section><button class="primary wide submitAnswer" data-action="submit" ${selected.length?'':'disabled'}>Submit answer</button></main>`)}
function finishAnswer(correct:boolean){const s=state.activeSession!,a=s.activities[s.index];s.index++;feedback={a,correct,selected:[...selected],attempts:attempt,responseTimeSeconds:Math.round((Date.now()-activityStarted)/1000),preAnswerFlag,exam:s.mode==='exam',committed:false};save();view='feedback';render()}
function commitAnswer(rating:Confidence){if(!feedback||feedback.committed)return;confidence=rating;const {a,correct}=feedback,p=state.progress[a.conceptId],guess=rating==='Guessed'||rating==='No idea'||Boolean(feedback.preAnswerFlag),interval=!correct?1:guess?1:feedback.attempts>1?3:7,mastery=Math.max(0,Math.min(100,p.mastery+(correct?(guess?3:12):-8))),order:Stage[]=['unseen','introduced','recognised','understood','applied','retained','exam-ready'];let si=order.indexOf(p.stage);if(correct&&!guess)si=Math.min(order.length-1,Math.max(1,si+1));else if(p.stage==='unseen')si=1;const misconception=!correct?(a.confusionWith||feedback.preAnswerFlag||'precision_vs_related_term'):feedback.preAnswerFlag||'';const np={...p,stage:order[si],mastery,attempts:p.attempts+1,correct:p.correct+(correct?1:0),guesses:p.guesses+(guess?1:0),misconceptions:misconception?[...new Set([...p.misconceptions,misconception])]:p.misconceptions,nextReview:addDays(interval),lastSeen:iso(),recognition:Math.max(p.recognition,correct?mastery:0),understanding:Math.max(p.understanding,correct&&!guess?mastery-8:0),application:Math.max(p.application,correct&&a.type.includes('scenario')?mastery-5:0),scenarioTransfer:Math.max(p.scenarioTransfer,correct&&a.type.includes('scenario')?mastery:0),confidenceAccuracy:Math.round((p.confidenceAccuracy*p.attempts+(correct&&!guess?100:correct?35:rating==='I knew it'?0:50))/(p.attempts+1)),responseTimes:[...p.responseTimes.slice(-19),feedback.responseTimeSeconds]};if(!state.activeSession?.testOnly)state.progress[a.conceptId]=np;if(!state.activeSession?.testOnly)state.events.push(emit('activity_answered',[a.conceptId],{activityId:a.id,activityType:a.type,qualityStatus:a.qualityStatus,selected:feedback.selected,correct,correctAnswer:a.correct,attempts:feedback.attempts,confidence:rating,preAnswerFlag:feedback.preAnswerFlag||null,responseTimeSeconds:feedback.responseTimeSeconds,nextReview:np.nextReview,testOnly:false},a.unitId));const previousStage=p.stage,newStage=np.stage,stageCoins:Record<Stage,number>={unseen:0,introduced:0,recognised:0,understood:2,applied:3,retained:5,'exam-ready':10};
const xp=correct&&rating==='I knew it'&&feedback.attempts===1?2:correct?1:0;let coins=0;
const session=state.activeSession,testOnly=Boolean(session?.testOnly);
if(!testOnly){state.xp+=xp;if(previousStage!==newStage&&stageCoins[newStage]>0){const key=`stage:${a.conceptId}:${newStage}`;if(awardOnce(key,stageCoins[newStage],'stage_rewarded',{conceptId:a.conceptId,stage:newStage}))coins=stageCoins[newStage]}if(session?.bossId&&correct)session.bossCorrect=(session.bossCorrect||0)+1}else{state.testMode.coins+=correct?1:0}
if((!correct||guess)&&state.activeSession&&!state.activeSession.testOnly&&state.activeSession.mode!=='exam'){const repeat=makeActivity(records.find(r=>r.conceptId===a.conceptId),'Reinforcement after an incorrect or low-confidence answer');repeat.options=[...repeat.options].sort(()=>Math.random()-.5);state.activeSession.activities.splice(Math.min(state.activeSession.index+2,state.activeSession.activities.length),0,repeat)}feedback={...feedback,confidence:rating,np,committed:true,xp,coins};checkAchievements();save();render()}
function feedbackView(){
 const {a,correct,selected:sel,committed,exam}=feedback;
 if(!committed)return shell(`<main class="shell feedbackScreen"><section class="card feedback ${correct?'correct':'wrong'}"><p class="eyebrow">${exam?'ANSWER RECORDED':correct?'CORRECT':'NOT CORRECT'}</p><h1>${exam?'How confident were you?':correct?'Correct':'Not correct'}</h1><p><b>Selected answer:</b> ${esc(sel.join(', ')||'No response')}</p>${correct?'':`<p><b>Correct answer:</b> ${esc(a.correct.join(', '))}</p>`}<h2>How confident were you?</h2><div class="postAnswerConfidence">${(['I knew it','Fairly sure','Guessed','No idea'] as Confidence[]).map(c=>`<button data-rating="${c}">${c}</button>`).join('')}</div></section></main>`);
 const low=correct&&(feedback.confidence==='Guessed'||feedback.confidence==='No idea');
 const other=Object.entries(a.distractorReasons).filter(([k])=>!sel.includes(k)).map(([k,v])=>`<p><b>${esc(k)}:</b> ${esc(v)}</p>`).join('');
 if(correct)return shell(`<main class="shell feedbackScreen"><section class="card feedback correct"><p class="eyebrow">${low?'CORRECT, BUT LOW CONFIDENCE':'CORRECT'}</p><h1>${low?'Correct, but low confidence':'Correct'}</h1><p><b>Selected answer:</b> ${esc(sel.join(', '))}</p><p class="shortExplanation">${esc(a.reason)}</p><div class="cue"><b>Memory cue</b><p>${esc(a.memoryCue)}</p></div>${low?'<p class="notice">Brief reinforcement scheduled sooner because confidence was low.</p>':''}<details open class="explanationPanel"><summary>Why this is correct</summary><p>${esc(a.reason)}</p></details><details class="explanationPanel"><summary>Why each other option is wrong</summary>${other}</details><details class="explanationPanel"><summary>Exam tip</summary><p>${esc(a.examTrap)}</p></details><details class="explanationPanel"><summary>Microsoft/MSP example</summary><p>${esc(a.microsoftExample)}</p><p>${esc(a.mspExample)}</p></details><p class="reward">+${feedback.xp||0} XP${feedback.coins?` · +${feedback.coins} coins`:''}</p><button class="primary wide" data-action="continue">Continue</button></section></main>`);
 const misconception=a.confusionWith||feedback.preAnswerFlag||'A related term was selected instead of the most precise answer.';
 return shell(`<main class="shell feedbackScreen"><section class="card feedback wrong"><p class="eyebrow">NOT CORRECT</p><h1>Not correct</h1><p><b>Your selected answer:</b> ${esc(sel.join(', ')||'No response')}</p><p><b>Correct answer:</b> ${esc(a.correct.join(', '))}</p><details open class="explanationPanel"><summary>Why your selected answer was tempting</summary><p>${esc(a.commonWrongTemptation||'It is related to the topic, but it does not satisfy the requirement as precisely.')}</p></details><details open class="explanationPanel"><summary>Why the correct answer is better</summary><p>${esc(a.reason)}</p></details><details class="explanationPanel"><summary>Why the remaining options are wrong</summary>${other}</details><div class="trap"><b>Misconception detected</b><p>${esc(misconception)}</p></div><div class="cue"><b>Memory cue</b><p>${esc(a.memoryCue)}</p></div><details class="explanationPanel"><summary>Exam tip</summary><p>${esc(a.examTrap)}</p></details><details class="explanationPanel"><summary>Targeted remediation</summary><p>Review the purpose, timing and scope of both the selected and correct options, then answer a differently worded version.</p></details><div class="feedbackActions"><button data-action="retest">Retest now</button><button class="primary" data-action="continue">Continue</button></div></section></main>`)
}
function bossResultView(){const b=state.bossHistory.at(-1);if(!b)return dashboard();const weak=Object.values(state.progress).filter(p=>p.misconceptions.length||p.mastery<50).slice(0,5);return shell(`<main class="shell"><section class="card bossResult ${b.passed?'defeated':'survived'}"><p class="eyebrow">${b.passed?'BOSS DEFEATED':'BOSS SURVIVED'}</p><h1>${b.score}%</h1><p>${b.passed?'Pass threshold met. Reward issued once.':'No penalty. Review the weak concepts and retry when ready.'}</p><h2>Weak concepts</h2>${weak.map(p=>`<p>${esc(records.find(r=>r.conceptId===p.conceptId)?.name||p.conceptId)}</p>`).join('')||'<p>No specific weak concept detected.</p>'}${b.passed?'<button class="primary wide" data-nav="home">Continue</button>':'<div class="feedbackActions"><button data-mode="mistakes" data-minutes="5">Start targeted review</button><button data-nav="review">Retry later</button></div>'}</section></main>`)}
function dashboard(){const ps=Object.values(state.progress),domains=['1','2','3','4','5'].map(d=>{const rs=assessable.filter(r=>String(r.objective).startsWith(d+'.')).map(r=>state.progress[r.conceptId]);return {d,score:Math.round(rs.reduce((a,p)=>a+p.mastery,0)/Math.max(1,rs.length))}}),ready=Math.round(domains.reduce((a,x)=>a+x.score,0)/5/5)*5,due=ps.filter(p=>p.nextReview&&new Date(p.nextReview)<=new Date()).length;return shell(`<main class="shell"><h1>Readiness analytics</h1><p class="notice">Pass readiness is an estimate, not a guarantee. Values are rounded to avoid false precision.</p><section class="metrics"><article><b>${ready}%</b><span>Estimated pass readiness</span></article><article><b>${due}</b><span>Overdue reviews</span></article><article><b>${ps.filter(p=>p.stage==='exam-ready').length}</b><span>Exam-ready records</span></article><article><b>${state.events.length}</b><span>Study events</span></article></section><section class="card"><h2>Readiness by domain</h2>${domains.map(x=>`<div class="mastery"><b>Domain ${x.d}.0: ${x.score}%</b><div class="progress"><i style="width:${x.score}%"></i></div></div>`).join('')}</section><section class="card"><h2>Learning stages</h2>${(['unseen','introduced','recognised','understood','applied','retained','exam-ready'] as Stage[]).map(s=>`<p><b>${s}:</b> ${ps.filter(p=>p.stage===s).length}</p>`).join('')}</section><section class="card"><h2>Weak comparisons</h2>${ps.filter(p=>p.misconceptions.length).slice(0,15).map(p=>`<p><b>${esc(records.find(r=>r.conceptId===p.conceptId)?.name)}:</b> ${esc(p.misconceptions.join(', ').replaceAll('_',' '))}</p>`).join('')||'<p>None recorded.</p>'}</section></main>`)}
