function reviewView(){const ps=Object.values(state.progress),due=ps.filter(p=>p.nextReview&&new Date(p.nextReview)<=new Date()).length,mistakes=ps.filter(p=>p.attempts>p.correct||p.misconceptions.length).length,low=ps.filter(p=>p.guesses||p.confidenceAccuracy<55&&p.attempts).length;const options=[['adaptive','Continue learning','Mixed high-value session'],['due','Reviews due',`${due} concepts due`],['mistakes','Fix my mistakes',`${mistakes} weak concepts`],['low-confidence','Low confidence',`${low} uncertain concepts`],['acronym','Weak acronyms','Acronym recognition and context'],['comparison','Comparison practice','Recurring confusion pairs'],['boss','Boss battle','Short milestone challenge']];return shell(`<main class="shell"><h1>Adaptive review</h1><p>Choose the type of evidence you want to strengthen.</p>${options.map(([m,n,d])=>`<section class="card reviewCard"><h2>${n}</h2><p>${d}</p><div class="durationGrid">${[[.5,'30s'],[1,'1m'],[2,'2m'],[5,'5m'],[10,'10m']].map(([min,l])=>`<button data-mode="${m}" data-minutes="${min}">${l}</button>`).join('')}</div></section>`).join('')}</main>`)}
function achievementsView(){return shell(`<main class="shell">${state.testMode.enabled?'<p class="eyebrow">TEST PREVIEW</p>':''}<h1>Achievements</h1><section class="profileSummary">${shieldMarkup('large')}<div><h2>${esc(learnerName())} · Level ${level()}</h2><p>${state.achievements.length}/${achievementDefs.length} unlocked</p></div></section>${achievementDefs.map(a=>{const value=Math.min(a.target,a.progress()),unlocked=state.achievements.includes(a.id),pct=Math.round(value/a.target*100);return `<section class="card achievement ${unlocked?'unlocked':'locked'}"><div class="row"><h2>${unlocked?'★':'○'} ${a.name}</h2><span>${a.coins} coins</span></div><div class="progress"><i style="width:${pct}%"></i></div><p>${unlocked?'Unlocked from real study evidence.':`${value}/${a.target}`}</p></section>`}).join('')}</main>`)}
const cosmeticCatalogue=[['theme-blue','Blue theme',0],['theme-purple','Purple theme',40],['theme-green','Green theme',40],['theme-oled','OLED black',60],['card-glass','Glass cards',35],['card-flat','Flat cards',25],['border-bronze','Bronze border',30],['border-neon','Neon border',60],['shield-gold-style','Angular shield style',75],['avatar-sentinel','Shield Sentinel avatar',50],['background-grid','Security grid background',45],['motion-subtle','Subtle motion style',30]];
function cosmeticsView(){return shell(`<main class="shell">${state.testMode.enabled?'<p class="eyebrow">TEST PREVIEW</p>':''}<h1>Cosmetics</h1><p>Cosmetics never alter learning content, mastery or readiness.</p><section class="card">${shieldMarkup('large')}<p>${state.testMode.enabled?`Real coins: ${state.coins} · Test coins: ${state.testMode.unlimitedCoins?'Unlimited':state.testMode.coins}`:`${state.coins} coins available`}</p></section>${cosmeticCatalogue.map(([idn,name,cost])=>{const owned=state.cosmetics.owned.includes(String(idn)),equipped=state.cosmetics.equippedTheme===idn||state.cosmetics.equippedShield===idn;return `<section class="card cosmetic"><div><h2>${esc(name)}</h2><p>${equipped?'Equipped':owned?'Owned':`${cost} coins`}</p></div><button data-cosmetic="${idn}" data-cost="${cost}">${equipped?'Equipped':owned?'Equip':'Unlock'}</button></section>`}).join('')}</main>`)}
function reportsView(){return shell(`<main class="shell"><h1>Question reports</h1><p>Reports stay on this device and are included in backups.</p><button data-action="export-reports">Export reports</button>${state.questionReports.slice().reverse().map(r=>`<section class="card"><div class="row"><span class="pill">${esc(r.reason)}</span><span>${new Date(r.createdAt).toLocaleDateString()}</span></div><p><b>${esc(records.find(x=>x.conceptId===r.conceptId)?.name||r.conceptId)}</b></p><p>${esc(r.details||'No additional details.')}</p></section>`).join('')||'<section class="card"><p>No reports saved.</p></section>'}</main>`)}
function aiPanel(){if(!aiOpen)return '';const a=feedback?.a||state.activeSession?.activities[state.activeSession.index]||null,r=a?records.find(x=>x.conceptId===a.conceptId):currentUnit?records.find(x=>x.conceptId===currentUnit.conceptIds[lessonIndex]):null;return `<div class="sheetBackdrop" data-action="close-ai"><section class="bottomSheet" role="dialog" aria-modal="true" aria-label="Grounded tutor"><div class="sheetHandle"></div><div class="row"><h2>Grounded tutor</h2><button data-action="close-ai">Close</button></div><p class="notice">Offline deterministic tutor. It uses the approved curriculum context and cannot provide open-ended remote AI answers.</p><h3>${esc(r?.name||a?.correct?.[0]||'Current concept')}</h3><div class="quickPrompts">${['Explain more simply','Explain like I’m new','Use an analogy','Microsoft example','MSP example','Compare concepts','Why was my answer wrong?','Give me an exam tip','Test me again'].map(q=>`<button data-tutor="${q}">${q}</button>`).join('')}</div><div id="tutor-output" class="tutorOutput"><b>Current explanation</b><p>${esc(a?.reason||`Focus on the purpose, timing, and scope of ${r?.name||'the current concept'}.`)}</p><p><b>Memory cue:</b> ${esc(a?.memoryCue||r?.objectiveBranch||'Use the most precise official term.')}</p></div></section></div>`}
function reportPanel(){if(!reportOpen)return '';const a=feedback?.a||state.activeSession?.activities[state.activeSession.index];return `<div class="sheetBackdrop"><section class="bottomSheet" role="dialog" aria-modal="true"><div class="row"><h2>Report question</h2><button data-action="close-report">Close</button></div><p>${esc(a?.prompt||'Current question')}</p><label>Reason <select id="report-reason">${['poor wording','unrealistic scenario','wrong explanation','wrong answer','multiple possible answers','typo','too easy','too hard','outside exam scope','other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Details <textarea id="report-details" placeholder="What should be improved?"></textarea></label><button class="primary wide" data-action="save-report">Save report</button></section></div>`}
function shieldMarkup(size='normal'){
  const id=state.testMode.enabled&&state.testMode.previewShield?state.testMode.previewShield:state.cosmetics.equippedShield;
  const name=id.replace('shield-','').replaceAll('-',' ');
  return `<div class="profileShield ${esc(id)} ${esc(size)}" aria-label="${esc(name)} shield"><span>◆</span><b>${esc(name)}</b></div>`;
}
function bossConsole(s:Session){
  if(!s.bossId)return '';
  const total=s.activities.length,done=s.index,correct=s.bossCorrect||0,hp=Math.max(0,100-Math.round(correct/Math.max(1,total)*100));
  const frames=['[=== SECURITY WRAITH ===]','[==  SECURITY WRAITH  ==]','[=   SECURITY WRAITH   =]'];
  const frame=frames[Math.min(frames.length-1,Math.floor(correct/Math.max(1,total)*frames.length))];
  const log=done===0?'BOSS DETECTED. SELECT THE BEST RESPONSE.':correct===0?'ATTACK BLOCKED. ANALYSE THE NEXT SCENARIO.':hp===0?'FINAL STRIKE READY. COMPLETE THE BATTLE.':`SHIELD IMPACT. ${correct} HIT${correct===1?'':'S'} LANDED.`;
  return `<section class="bossTerminal ${state.testMode.animation==='critical'?'criticalPreview':''}" aria-label="Text battle display"><pre>${esc(frame)}
      /\\_/
  ___( o.o )___
 /___  >^<  ___\\
     \\___/</pre><div class="terminalLine">&gt; ${esc(log)}</div><div class="terminalStats"><span>HP ${hp}%</span><span>HITS ${correct}/${total}</span><span>ROUND ${Math.min(done+1,total)}/${total}</span></div></section>`;
}
function visualTestLab(){if(!state.testMode.enabled)return aboutView();const shields=['shield-basic','shield-bronze','shield-silver','shield-gold','shield-platinum','shield-diamond','shield-master'];const cosmetics=cosmeticCatalogue.map(x=>String(x[0]));return shell(`<main class="shell testLab"><p class="eyebrow">TEST PREVIEW</p><h1>Developer Lab</h1><p class="testWarning"><b>TEST MODE</b> Test actions do not affect genuine mastery, readiness or rewards.</p><section class="card"><h2>Test profile</h2><button class="primary wide" data-action="test-unlock-everything">UNLOCK EVERYTHING FOR TESTING</button><p><b>Real coins:</b> ${state.coins} · <b>Test coins:</b> ${state.testMode.unlimitedCoins?'Unlimited':state.testMode.coins}</p><button data-action="test-lock-all">Lock all test items</button><button data-action="test-unlimited">Set test coins to unlimited</button><button data-test-grant="100">Grant 100 test coins</button><button data-test-grant="10000">Grant 10,000 test coins</button><button data-action="test-reset">Reset test-only data</button></section><section class="card"><h2>Shields</h2>${shieldMarkup('large')}<div class="previewGrid">${shields.map(x=>`<button data-test-shield="${x}">Preview ${x.replace('shield-','')}</button>`).join('')}</div><button data-test-animation="rank-up">Preview shield rank-up</button></section><section class="card"><h2>Achievements</h2>${[['locked','Locked achievement'],['partial','Partial progress'],['almost','Almost complete'],['unlocked','Achievement unlocked'],['queued','Multiple queued achievements'],['complete','Completed gallery']].map(x=>`<button data-achievement-state="${x[0]}">${x[1]}</button>`).join('')}</section><section class="card"><h2>Feedback</h2>${[['feedback-correct','Correct answer'],['feedback-low','Correct but low confidence'],['feedback-wrong','Incorrect answer'],['dontknow','I don’t know'],['teach','Teach me'],['forgot','I forgot'],['confusing','Confusion comparison'],['retest','Answer retest']].map(x=>`<button data-test-overlay="${x[0]}">Preview ${x[1]}</button>`).join('')}</section><section class="card"><h2>Notifications</h2><button data-notification-preview="success">Success</button><button data-notification-preview="achievement">Achievement</button><button data-notification-preview="coins">Coins</button><button data-notification-preview="shield">Shield</button><button data-notification-preview="error">Error</button><button data-action="test-notification-queue">Multiple queued notifications</button></section><section class="card"><h2>Bosses</h2><button data-test-boss="boss">Any Unit Boss</button><button data-test-boss="boss-objective">Any Objective Boss</button><button data-test-boss="boss-domain">Any Domain Boss</button><button data-test-boss="boss-final">Final Readiness Boss</button>${['all-correct','threshold','below-threshold','perfect','entrance','hit','critical','defeated','survived','claimed','repeat'].map(x=>`<button data-boss-scenario="${x}">${x.replaceAll('-',' ')}</button>`).join('')}</section><section class="card"><h2>Question and lesson states</h2><button data-test-screen="session">Start reviewed question</button><button data-test-overlay="concept-card">Concept card</button><button data-test-overlay="lesson-empty">No-question lesson</button><button data-test-overlay="report">Question report flow</button><button data-test-overlay="exam-empty">Exam Mode empty state</button></section><section class="card"><h2>Application states</h2>${['home','learn','review','dashboard','more','settings','backup','memory','achievements','cosmetics','reports','about'].map(x=>`<button data-test-screen="${x}">Open ${x}</button>`).join('')}<button data-test-overlay="offline">Offline state</button><button data-test-overlay="update">Update available</button><button data-test-overlay="updated">Update installed</button><button data-test-overlay="import-success">Import success</button><button data-test-overlay="import-failure">Import failure</button><button data-test-overlay="backup-reminder">Backup reminder</button><button data-test-overlay="empty">Empty state</button></section><section class="card"><button class="primary wide" data-action="test-exit">Exit Test Mode</button></section></main>`)}

